'use client';

import { useEffect, useState, use, useRef, Suspense } from 'react';
import { useRouter } from 'next/navigation';
import { getDocumentById, updateDocument, shareDocument, DocumentItem } from '@/lib/api';
import { ArrowLeft, Save, Share2, Bold, Italic, Underline, Heading1, List, Check, Loader2 } from 'lucide-react';

function EditorContent({ docId }: { docId: string }) {
  const router = useRouter();

  const [document, setDocument] = useState<DocumentItem | null>(null);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [saving, setSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<string | null>(null);
  const [shareTarget, setShareTarget] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    getDocumentById(docId)
      .then((doc) => {
        setDocument(doc);
        setTitle(doc.title);
        setContent(doc.content || '');
      })
      .catch((err) => console.error('Error loading doc:', err));
  }, [docId]);

  // Auto-save effect
  useEffect(() => {
    if (!document) return;
    const timer = setTimeout(async () => {
      try {
        setSaving(true);
        await updateDocument(docId, title, content);
        setSaving(false);
        setLastSaved(new Date().toLocaleTimeString());
      } catch (error) {
        console.error('Auto-save error:', error);
        setSaving(false);
      }
    }, 1000);

    return () => clearTimeout(timer);
  }, [title, content, docId, document]);

  // Fixed formatting handler for textarea selection
  const handleFormat = (prefix: string, suffix = '') => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = content.substring(start, end);
    
    const replacement = prefix + (selectedText || 'text') + suffix;
    const newContent = content.substring(0, start) + replacement + content.substring(end);

    setContent(newContent);
    
    // Reset cursor position after insertion
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(start + prefix.length, end + prefix.length);
    }, 0);
  };

  const handleShare = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!shareTarget) return;
    try {
      await shareDocument(docId, shareTarget);
      alert(`Document successfully shared with ${shareTarget}!`);
      setShareTarget('');
      setShowShareModal(false);
    } catch (error) {
      console.error('Sharing error:', error);
    }
  };

  if (!document) {
    return <div className="text-center py-20 text-xs font-semibold text-slate-400">Loading editor...</div>;
  }

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col">
      {/* Editor Top Bar */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-3 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-3">
          <button
            onClick={() => router.push('/')}
            className="p-2 hover:bg-slate-100 rounded-xl text-slate-600 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="text-base font-bold text-slate-900 bg-transparent hover:bg-slate-50 focus:bg-white px-2 py-1 rounded-lg border border-transparent focus:border-indigo-300 focus:outline-none transition-all w-64 sm:w-96"
          />
        </div>

        <div className="flex items-center space-x-4">
          <div className="text-xs text-slate-400 font-medium flex items-center space-x-1.5">
            {saving ? (
              <>
                <Loader2 className="w-3.5 h-3.5 animate-spin text-indigo-600" />
                <span>Saving...</span>
              </>
            ) : lastSaved ? (
              <>
                <Check className="w-3.5 h-3.5 text-emerald-600" />
                <span>Saved at {lastSaved}</span>
              </>
            ) : null}
          </div>

          <button
            onClick={() => setShowShareModal(true)}
            className="inline-flex items-center space-x-1.5 bg-indigo-50 text-indigo-700 hover:bg-indigo-100 px-3.5 py-2 rounded-xl text-xs font-bold transition-colors"
          >
            <Share2 className="w-4 h-4" />
            <span>Share</span>
          </button>
        </div>
      </header>

      {/* Formatting Toolbar */}
      <div className="bg-white border-b border-slate-200 px-6 py-2 flex items-center space-x-1 shadow-sm overflow-x-auto">
        <button
          onClick={() => handleFormat('**', '**')}
          title="Bold"
          className="p-2 hover:bg-slate-100 rounded-lg text-slate-700 font-bold transition-colors cursor-pointer"
          type="button"
        >
          <Bold className="w-4 h-4" />
        </button>
        <button
          onClick={() => handleFormat('*', '*')}
          title="Italic"
          className="p-2 hover:bg-slate-100 rounded-lg text-slate-700 italic transition-colors cursor-pointer"
          type="button"
        >
          <Italic className="w-4 h-4" />
        </button>
        <button
          onClick={() => handleFormat('<u>', '</u>')}
          title="Underline"
          className="p-2 hover:bg-slate-100 rounded-lg text-slate-700 underline transition-colors cursor-pointer"
          type="button"
        >
          <Underline className="w-4 h-4" />
        </button>
        <div className="h-4 w-px bg-slate-200 mx-2" />
        <button
          onClick={() => handleFormat('# ')}
          title="Heading"
          className="p-2 hover:bg-slate-100 rounded-lg text-slate-700 transition-colors cursor-pointer"
          type="button"
        >
          <Heading1 className="w-4 h-4" />
        </button>
        <button
          onClick={() => handleFormat('- ')}
          title="Bullet List"
          className="p-2 hover:bg-slate-100 rounded-lg text-slate-700 transition-colors cursor-pointer"
          type="button"
        >
          <List className="w-4 h-4" />
        </button>
      </div>

      {/* Writing Canvas */}
      <main className="max-w-4xl mx-auto w-full flex-1 p-6 sm:p-10">
        <div className="bg-white border border-slate-200 shadow-sm rounded-2xl min-h-[700px] p-8 sm:p-12">
          <textarea
            ref={textareaRef}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Start typing your document content here..."
            className="w-full h-full min-h-[600px] bg-transparent resize-none focus:outline-none text-slate-800 text-sm sm:text-base leading-relaxed font-normal"
          />
        </div>
      </main>

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-xl border border-slate-100">
            <h3 className="text-base font-bold text-slate-900 mb-2">Share Document</h3>
            <p className="text-xs text-slate-500 mb-4">
              Grant access to another user (e.g., <span className="font-semibold text-slate-700">user_2</span>).
            </p>

            <form onSubmit={handleShare} className="space-y-4">
              <input
                type="text"
                placeholder="Enter User ID (e.g. user_2)"
                value={shareTarget}
                onChange={(e) => setShareTarget(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 text-xs px-4 py-3 rounded-xl text-slate-800 focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />

              <div className="flex justify-end space-x-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowShareModal(false)}
                  className="px-4 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 text-xs font-semibold bg-indigo-600 text-white rounded-xl shadow-sm hover:bg-indigo-700 transition-colors"
                >
                  Grant Access
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

// Parent Wrapper with Suspense boundary to satisfy Next.js 15+ dynamic route prerendering requirements
function EditorWrapper({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params);
  return <EditorContent docId={resolvedParams.id} />;
}

export default function EditorPage({ params }: { params: Promise<{ id: string }> }) {
  return (
    <Suspense fallback={<div className="text-center py-20 text-xs font-semibold text-slate-400">Loading editor...</div>}>
      <EditorWrapper params={params} />
    </Suspense>
  );
}